function TodoBoard({ workspaceId }) {
  return <TodoList key={workspaceId} />;
}

function TodoList() {
  const { items, addOne, removeOne, getResource } = useCollection<Todo>({
    getId: (t) => t.id,
  });

  return (
    <ul>
      {items.map((t) => (
        <TodoRow
          key={t.id}
          resource={getResource(t.id)}
          onRemove={() => removeOne(t.id)}
        />
      ))}
    </ul>
  );
}
